import glob

pdf_files = sorted(glob.glob("paper*.pdf"))

for pdf_file in pdf_files:
    print(f"--- {pdf_file} ---")
    try:
        doc = fitz.open(pdf_file)
        if len(doc) > 0:
            text = doc[0].get_text()
            print(text[:2000])  # Print first 2000 chars
        else:
            print("Empty PDF")
        doc.close()
    except Exception as e:
        print(f"Error reading {pdf_file}: {e}")
    print("\n" + "="*30 + "\n")

